// ─── Initialise persistent state ────────────────────────────────────
let s = context.get('state');
if (!s) {
    s = {
        Tank1_Temperature : 55.0,
        Temp_Setpoint     : 75.0,
        Main_Pressure     : 2.5,
        Flow_Rate         : 150.0,
        Conductivity      : 20.0,
        pH_Level          : 7.5,
        Caustic_Level     : 80.0,
        Caustic_Conc      : 2.0,
        Water_Level       : 90.0,
        Pump1_Speed       : 0.0,
        Pump2_Speed       : 0.0,
        System_Running    : true,
        HotWater_Level    : 85.0,
        HotWater_Temp     : 78.0,
        Recovery_Level    : 40.0,
        Recovery_Temp     : 58.0,
        Recovery_TDS      : 150.0,
        Fresh_Level       : 95.0,
        Fresh_Temp        : 22.0,
        Water_Usage       : 0.0,
        cycleStatus       : 'running',
        cycleStep         : 0,
        cycleProgress     : 0.0,
        cycleTimeRemaining: 3600,
        tick              : 0,
        alarmIdCounter    : 1
    };
}

const rnd  = (lo, hi) => lo + Math.random() * (hi - lo);
const bump = (v, lo, hi, delta) => Math.min(hi, Math.max(lo, v + rnd(-delta, delta)));

s.tick += 1;

// ─── Simulate CIP cycle steps ───────────────────────────────────────
const steps = [
    { name: 'Pre-Rinse',     duration: 600  },
    { name: 'Caustic Wash',  duration: 1800 },
    { name: 'Intermediate Rinse', duration: 600 },
    { name: 'Acid Wash',     duration: 1200 },
    { name: 'Final Rinse',   duration: 600  },
    { name: 'Dry / Complete', duration: 300 }
];
const totalDuration = steps.reduce((a, b) => a + b.duration, 0);
const elapsed = (s.tick * 2) % totalDuration;
let acc = 0, stepIdx = 0;
for (let i = 0; i < steps.length; i++) {
    acc += steps[i].duration;
    if (elapsed < acc) { stepIdx = i; break; }
}
s.cycleStep         = stepIdx;
s.cycleProgress     = parseFloat(((elapsed / totalDuration) * 100).toFixed(1));
s.cycleTimeRemaining = totalDuration - elapsed;

// ─── CIP process physics ─────────────────────────────────────────────
if (s.System_Running) {
    s.Pump1_Speed = bump(s.Pump1_Speed || 80, 75, 90, 1);
    s.Pump2_Speed = bump(s.Pump2_Speed || 80, 75, 90, 1);
    s.Flow_Rate   = bump(s.Flow_Rate,  130, 170, 3);
    s.Main_Pressure = bump(s.Main_Pressure, 2.2, 2.8, 0.05);

    // Temperature climbs toward setpoint
    const diff = s.Temp_Setpoint - s.Tank1_Temperature;
    s.Tank1_Temperature += (diff > 0 ? 0.4 : -0.2) + rnd(-0.15, 0.15);

    // Accumulate water usage
    s.Water_Usage += parseFloat(((s.Flow_Rate / 60) * 2).toFixed(3));
    if (s.Water_Usage > 999) s.Water_Usage = 999;

    // Levels drift
    s.Caustic_Level   = Math.max(10, s.Caustic_Level  - 0.04);
    s.HotWater_Level  = Math.max(10, s.HotWater_Level - 0.03);
    s.Fresh_Level     = Math.max(10, s.Fresh_Level    - 0.03);
    s.Recovery_Level  = Math.min(90, s.Recovery_Level + 0.03);
    s.Water_Level     = Math.max(10, s.Water_Level    - 0.05);
} else {
    s.Pump1_Speed = 0;
    s.Pump2_Speed = 0;
    s.Flow_Rate   = 0;
    s.Main_Pressure = 0;
    s.Tank1_Temperature = Math.max(20, s.Tank1_Temperature - 0.1);
}

// ─── Noise on auxiliary readings ─────────────────────────────────────
s.Conductivity   = bump(s.Conductivity,   18,  24, 0.5);
s.pH_Level       = bump(s.pH_Level,        7.2, 7.8, 0.05);
s.Caustic_Conc   = bump(s.Caustic_Conc,   1.8, 2.2, 0.02);
s.HotWater_Temp  = bump(s.HotWater_Temp,  72,  84, 0.2);
s.Recovery_Temp  = bump(s.Recovery_Temp,  52,  66, 0.2);
s.Recovery_TDS   = bump(s.Recovery_TDS,  100, 200, 1);
s.Fresh_Temp     = bump(s.Fresh_Temp,     18,  25, 0.1);

// ─── Round numbers ───────────────────────────────────────────────────
Object.keys(s).forEach(k => {
    if (typeof s[k] === 'number') s[k] = parseFloat(s[k].toFixed(2));
});

// ─── Generate alarms ─────────────────────────────────────────────────
const alarms = [];
if (s.Tank1_Temperature > 85) {
    alarms.push({ id:'ALM-T01', device:'Tank 1', message:'Temperature critical high (>85°C)', severity:'Critical', status:'Pending', timestamp: new Date().toISOString() });
} else if (s.Tank1_Temperature > 80) {
    alarms.push({ id:'ALM-T02', device:'Tank 1', message:'Temperature warning (>80°C)', severity:'Warning', status:'Pending', timestamp: new Date().toISOString() });
}
if (s.Caustic_Level < 20) {
    alarms.push({ id:'ALM-C01', device:'Caustic Tank', message:'Caustic level low (<20%)', severity:'Warning', status:'Pending', timestamp: new Date().toISOString() });
}
if (s.Main_Pressure > 2.75) {
    alarms.push({ id:'ALM-P01', device:'Main Line', message:'Pressure high warning (>2.75 bar)', severity:'Warning', status:'Pending', timestamp: new Date().toISOString() });
}
if (s.pH_Level < 7.0 || s.pH_Level > 7.8) {
    alarms.push({ id:'ALM-PH01', device:'Caustic Tank', message:'pH out of range', severity:'Info', status:'Pending', timestamp: new Date().toISOString() });
}

s.activeAlarms = alarms;
context.set('state', s);

msg.payload = { state: s, steps, totalDuration };
return msg;

const s = context.get('state') || {};
const requestedIds = (msg.payload && msg.payload.tagIds) ? msg.payload.tagIds : [];

const values = requestedIds.map(id => ({
    name : id,
    id   : id,
    value: s[id] !== undefined ? s[id] : null,
    quality: 'Good',
    timestamp: new Date().toISOString()
}));

msg.payload = {
    values,
    timestamp: new Date().toISOString()
};
msg.statusCode = 200;
return msg;

const s = context.get('state') || {};
msg.payload = { alarms: s.activeAlarms || [] };
msg.statusCode = 200;
return msg;

const s = context.get('state') || {};
msg.payload = { alarms: s.alarmHistory || [] };
msg.statusCode = 200;
return msg;

const s = context.get('state') || {};
const steps = [
    { name: 'Pre-Rinse',          duration: 600  },
    { name: 'Caustic Wash',       duration: 1800 },
    { name: 'Intermediate Rinse', duration: 600  },
    { name: 'Acid Wash',          duration: 1200 },
    { name: 'Final Rinse',        duration: 600  },
    { name: 'Dry / Complete',     duration: 300  }
];
msg.payload = {
    status           : s.System_Running ? 'running' : 'idle',
    current_step     : s.cycleStep || 0,
    progress_percent : s.cycleProgress || 0,
    time_remaining   : s.cycleTimeRemaining || 0,
    steps
};
msg.statusCode = 200;
return msg;

msg.payload = { status: 'ok', source: 'Node-RED Simulator', timestamp: new Date().toISOString() };
msg.statusCode = 200;
return msg;
